// Deterministic DCF calculation engine.
// AI only ever supplies the raw assumptions below — every number in this
// file is computed with plain arithmetic, never generated by a model.

export const DEFAULT_ASSUMPTIONS = {
  companyName: "Company",
  baseRevenue: 5000000,
  revenueGrowth: [0.60, 0.45, 0.30, 0.20, 0.15],
  ebitdaMargin: 0.20,
  taxRate: 0.25,
  daPct: 0.03,
  capexPct: 0.03,
  nwcPct: 0.02,
  wacc: 0.12,
  terminalGrowth: 0.03,
  netDebt: 0,
  sharesOutstanding: 10000000,
};

const num = (v, fallback) => (typeof v === "number" && Number.isFinite(v) ? v : fallback);

// Fills in anything missing/malformed from an AI-supplied assumptions object
// with the defaults above, so the engine always has a complete, well-typed input.
export function validateAssumptions(raw) {
  const a = raw && typeof raw === "object" ? raw : {};
  const growth = Array.isArray(a.revenueGrowth)
    ? Array.from({ length: 5 }, (_, i) => num(a.revenueGrowth[i], DEFAULT_ASSUMPTIONS.revenueGrowth[i]))
    : DEFAULT_ASSUMPTIONS.revenueGrowth.slice();

  return {
    companyName: typeof a.companyName === "string" && a.companyName.trim()
      ? a.companyName.trim()
      : DEFAULT_ASSUMPTIONS.companyName,
    baseRevenue: num(a.baseRevenue, DEFAULT_ASSUMPTIONS.baseRevenue),
    revenueGrowth: growth,
    ebitdaMargin: num(a.ebitdaMargin, DEFAULT_ASSUMPTIONS.ebitdaMargin),
    taxRate: num(a.taxRate, DEFAULT_ASSUMPTIONS.taxRate),
    daPct: num(a.daPct, DEFAULT_ASSUMPTIONS.daPct),
    capexPct: num(a.capexPct, DEFAULT_ASSUMPTIONS.capexPct),
    nwcPct: num(a.nwcPct, DEFAULT_ASSUMPTIONS.nwcPct),
    wacc: num(a.wacc, DEFAULT_ASSUMPTIONS.wacc),
    terminalGrowth: num(a.terminalGrowth, DEFAULT_ASSUMPTIONS.terminalGrowth),
    netDebt: num(a.netDebt, DEFAULT_ASSUMPTIONS.netDebt),
    sharesOutstanding: num(a.sharesOutstanding, DEFAULT_ASSUMPTIONS.sharesOutstanding) || 1,
  };
}

// Computes the full 5-year unlevered DCF: projections, terminal value
// (Gordon growth), enterprise value, equity value, and implied share price.
export function computeDCF(rawAssumptions) {
  const a = validateAssumptions(rawAssumptions);
  const years = [];
  let revenue = a.baseRevenue;
  let sumPV = 0;

  for (let y = 1; y <= 5; y++) {
    revenue = revenue * (1 + a.revenueGrowth[y - 1]);
    const ebitda = revenue * a.ebitdaMargin;
    const da = revenue * a.daPct;
    const ebit = ebitda - da;
    // No tax benefit modeled on a negative EBIT year.
    const taxes = Math.max(ebit, 0) * a.taxRate;
    const nopat = ebit - taxes;
    const capex = revenue * a.capexPct;
    const nwcChange = revenue * a.nwcPct;
    const ufcf = nopat + da - capex - nwcChange;
    const discountFactor = 1 / Math.pow(1 + a.wacc, y);
    const pv = ufcf * discountFactor;
    sumPV += pv;
    years.push({ year: y, revenue, ebitda, da, ebit, taxes, nopat, capex, nwcChange, ufcf, discountFactor, pv });
  }

  const lastYear = years[years.length - 1];
  const terminalValid = a.wacc > a.terminalGrowth;
  const terminalValue = terminalValid
    ? (lastYear.ufcf * (1 + a.terminalGrowth)) / (a.wacc - a.terminalGrowth)
    : null;
  const pvTerminalValue = terminalValid ? terminalValue * lastYear.discountFactor : null;
  const enterpriseValue = terminalValid ? sumPV + pvTerminalValue : null;
  const equityValue = terminalValid ? enterpriseValue - a.netDebt : null;
  const impliedSharePrice = terminalValid ? equityValue / a.sharesOutstanding : null;

  return {
    assumptions: a,
    years,
    sumPV,
    terminalValue,
    pvTerminalValue,
    enterpriseValue,
    equityValue,
    impliedSharePrice,
    terminalValid,
  };
}

// Builds a symmetric range of `count` values centered on `center`, step apart.
export function sensitivityRange(center, step, count = 5) {
  const half = Math.floor(count / 2);
  return Array.from({ length: count }, (_, i) => center + (i - half) * step);
}

// 5x5 grid of implied share price across WACC (rows) and terminal growth
// (columns). Any cell where WACC <= terminal growth is flagged as an error
// instead of returning a number (the Gordon growth formula is undefined there).
export function computeSensitivity(rawAssumptions, opts = {}) {
  const a = validateAssumptions(rawAssumptions);
  const waccSteps = opts.waccSteps ?? sensitivityRange(a.wacc, 0.01, 5);
  const growthSteps = opts.growthSteps ?? sensitivityRange(a.terminalGrowth, 0.005, 5);

  const grid = waccSteps.map((wacc) =>
    growthSteps.map((terminalGrowth) => {
      if (wacc <= terminalGrowth) {
        return { wacc, terminalGrowth, error: true, price: null };
      }
      const { impliedSharePrice } = computeDCF({ ...a, wacc, terminalGrowth });
      return { wacc, terminalGrowth, error: false, price: impliedSharePrice };
    })
  );

  return { waccSteps, growthSteps, grid };
}
